INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 42, 'theory', 'Quiz: A Router and a Multithreaded Server');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 42, 0, 'When should the router reply 405 rather than 404?', '["When the path contains an error", "When a path pattern was found but it has no entry for the requested method", "When the body is too large", "When the server is overloaded"]', 1, '404 means there is no such resource at all; 405 means the resource exists but the method is not allowed for it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 42, 1, 'Why must the specific route /users/new be registered before /users/:id?', '["It is faster", "The order of entries sets the priority: otherwise \"new\" would be taken as the value of :id", "The compiler requires it", "Otherwise it will not compile"]', 1, 'The first matching entry wins.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 42, 2, 'How is a graceful shutdown of a thread pool implemented?', '["By forcibly killing the threads", "By closing the queue''s sender: workers finish accepted jobs and exit, and Drop waits for them with join", "By panicking in the threads", "By stopping the process"]', 1, 'When the channel is closed and empty, recv() returns an error and the worker loop ends.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 42, 3, 'Why pass "the current time" as a parameter to a token bucket?', '["So that it works faster", "So that the behavior can be tested without real waiting", "std requires it", "To avoid mutexes"]', 1, 'Deterministic time is the basis of testability for any code with timers.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 42, 4, 'How is an integration test of the server more useful than unit tests?', '["It is faster", "It checks the whole system: a real socket, the order of layers, headers, closing of connections", "It is not needed", "It replaces logs"]', 1, 'Such tests catch errors at the seams that you can''t see from individual functions.');
